TEE_Result asymmetric_signature_verify(unsigned long state,
                                       const struct utee_attribute *usr_params,
                                       size_t num_params,
                                       const void *data,
                                       size_t data_len,
                                       const void *sig,
                                       size_t sig_len) {
    TEE_Result res = TEE_SUCCESS;
    void *session = NULL;
    struct utee_attribute *attrs = NULL;

    /* Retrieve current session and check access rights */
    session = get_current_session(state);
    if (!session)
        return TEE_ERROR_BAD_PARAMETERS;

    if (!check_access_rights(session, data, data_len, sig, sig_len))
        return TEE_ERROR_ACCESS_DENIED;

    /* Allocate memory for attributes */
    attrs = calloc(num_params, sizeof(struct utee_attribute));
    if (!attrs)
        return TEE_ERROR_OUT_OF_MEMORY;

    memcpy(attrs, usr_params, num_params * sizeof(struct utee_attribute));

    /* Verify key initialization */
    if (!is_key_initialized(attrs))
        return TEE_ERROR_BAD_PARAMETERS;

    /* Determine the algorithm and perform verification */
    switch (attrs->algorithm) {
        case TEE_ALG_RSA_VERIFY:
            res = verify_rsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_DSA_VERIFY:
            res = verify_dsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_ECDSA_VERIFY:
            res = verify_ecdsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        default:
            res = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

    /* Free allocated memory */
    free(attrs);
    return res;
}

TEE_Result verify_asymmetric_signature(unsigned long state,
                                       const struct utee_attribute *usr_params,
                                       size_t num_params,
                                       const void *data,
                                       size_t data_len,
                                       const void *sig,
                                       size_t sig_len) {
    TEE_Result res = TEE_SUCCESS;
    void *session = NULL;
    struct utee_attribute *attrs = NULL;

    if (!usr_params || !data || !sig) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    session = get_current_session(state);
    if (!session) {
        return TEE_ERROR_ACCESS_DENIED;
    }

    if (!check_access_rights(session, data, data_len) ||
        !check_access_rights(session, sig, sig_len)) {
        return TEE_ERROR_ACCESS_CONFLICT;
    }

    attrs = malloc(num_params * sizeof(*attrs));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attrs, usr_params, num_params * sizeof(*attrs));

    res = verify_key_initialization(attrs);
    if (res != TEE_SUCCESS) {
        goto out;
    }

    switch (attrs->algorithm) {
        case ALG_RSA:
            res = verify_rsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case ALG_DSA:
            res = verify_dsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case ALG_ECDSA:
            res = verify_ecdsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        default:
            res = TEE_ERROR_NOT_SUPPORTED;
    }

out:
    free(attrs);
    return res;
}

TEE_Result verify_asymmetric_signature(unsigned long state,
                                       const struct utee_attribute *usr_params,
                                       size_t num_params,
                                       const void *data,
                                       size_t data_len,
                                       const void *sig,
                                       size_t sig_len) {
    TEE_Result result = TEE_SUCCESS;
    struct session *session = get_current_session();

    if (!session || !usr_params || !data || !sig) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    if (!check_access_rights(session, data, data_len, sig, sig_len)) {
        return TEE_ERROR_ACCESS_DENIED;
    }

    struct utee_attribute *attrs = malloc(num_params * sizeof(struct utee_attribute));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (size_t i = 0; i < num_params; ++i) {
        attrs[i] = usr_params[i];
    }

    if (!is_key_initialized(attrs)) {
        result = TEE_ERROR_BAD_STATE;
        goto cleanup;
    }

    const uint32_t algorithm = get_algorithm_from_state(state);
    switch (algorithm) {
        case TEE_ALG_RSA:
            result = verify_rsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_DSA:
            result = verify_dsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_ECDSA:
            result = verify_ecdsa_signature(attrs, data, data_len, sig, sig_len);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
    }

cleanup:
    free(attrs);
    return result;
}

TEE_Result verify_asymmetric_signature(unsigned long state,
                                       const struct utee_attribute *usr_params,
                                       size_t num_params,
                                       const void *data,
                                       size_t data_len,
                                       const void *sig,
                                       size_t sig_len) {
    TEE_Result res = TEE_SUCCESS;
    struct utee_session *session = NULL;
    struct utee_attribute *attrs = NULL;

    session = get_current_session(state);
    if (!session)
        return TEE_ERROR_BAD_PARAMETERS;

    if (!data || !sig) {
        res = TEE_ERROR_BAD_PARAMETERS;
        goto exit;
    }

    attrs = calloc(num_params, sizeof(struct utee_attribute));
    if (!attrs) {
        res = TEE_ERROR_OUT_OF_MEMORY;
        goto exit;
    }

    if (!is_key_initialized(session->key)) {
        res = TEE_ERROR_BAD_STATE;
        goto free_attrs;
    }

    if (session->algo == TEE_ALG_RSA) {
        res = verify_rsa_signature(session->key, data, data_len, sig, sig_len, attrs, num_params);
    } else if (session->algo == TEE_ALG_DSA) {
        res = verify_dsa_signature(session->key, data, data_len, sig, sig_len, attrs, num_params);
    } else if (session->algo == TEE_ALG_ECDSA) {
        res = verify_ecdsa_signature(session->key, data, data_len, sig, sig_len, attrs, num_params);
    } else {
        res = TEE_ERROR_NOT_SUPPORTED;
    }

free_attrs:
    free(attrs);
exit:
    return res;
}

TEE_Result verify_asymmetric_signature(
    unsigned long state,
    const struct utee_attribute* usr_params,
    size_t num_params,
    const void* data,
    size_t data_len,
    const void* sig,
    size_t sig_len) {
    TEE_Result res = TEE_SUCCESS;
    void* session = NULL;
    struct utee_attribute* attr = NULL;

    /* Retrieve session and check access rights */
    session = get_current_session(state);
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    if (!check_access_rights(session, data, data_len, sig, sig_len)) {
        return TEE_ERROR_ACCESS_DENIED;
    }

    /* Allocate memory for attributes */
    attr = (struct utee_attribute*)malloc(num_params * sizeof(struct utee_attribute));
    if (!attr) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attr, usr_params, num_params * sizeof(struct utee_attribute));

    /* Verify key initialization */
    if (!is_key_initialized(attr)) {
        res = TEE_ERROR_BAD_PARAMETERS;
        goto cleanup;
    }

    /* Perform signature verification based on algorithm */
    switch (get_algorithm(attr)) {
        case TEE_ALG_RSA:
            res = verify_rsa_signature(attr, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_DSA:
            res = verify_dsa_signature(attr, data, data_len, sig, sig_len);
            break;
        case TEE_ALG_ECDSA:
            res = verify_ecdsa_signature(attr, data, data_len, sig, sig_len);
            break;
        default:
            res = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

cleanup:
    if (attr) {
        free(attr);
    }

    return res;
}
